<template><div class="device-notices" ref="root"><button class="notice-trigger" :aria-expanded="open" aria-controls="device-notice-list" @click="open=!open">设备通知<span v-if="unread">{{unread}}</span></button><section v-if="open" id="device-notice-list" class="notice-popover" aria-label="设备通知"><header><h2>设备通知</h2><button v-if="unread" @click="markRead">全部已读</button></header><p class="notice-connection">{{connected?'设备事件已连接':'设备事件连接中'}}</p><ul v-if="notices.length"><li v-for="item in notices" :key="item.key" :class="{unread:!item.read}"><p>{{item.message}}</p><time>{{new Date(item.time).toLocaleString('zh-CN')}}</time></li></ul><p v-else class="notice-empty">本次会话暂无设备通知</p></section></div></template>
<script setup lang="ts">
import{ref,toRef,onMounted,onUnmounted}from'vue';import{useDeviceNotifications}from'../composables/useDeviceNotifications';const props=defineProps<{accountId:string}>();const{notices,connected,unread,markRead}=useDeviceNotifications(toRef(props,'accountId'));const open=ref(false),root=ref<HTMLElement>();function outside(e:MouseEvent){if(!root.value?.contains(e.target as Node))open.value=false}function escape(e:KeyboardEvent){if(e.key==='Escape'&&open.value){open.value=false;root.value?.querySelector<HTMLButtonElement>('button')?.focus()}}onMounted(()=>{document.addEventListener('click',outside);document.addEventListener('keydown',escape)});onUnmounted(()=>{document.removeEventListener('click',outside);document.removeEventListener('keydown',escape)});
</script>
<style scoped>.device-notices{position:relative}.notice-trigger{font-size:10px;border:0!important;background:none!important;padding:5px!important;display:flex;align-items:center;gap:6px}.notice-trigger span{background:#e8f1ff;color:var(--qs-accent);border-radius:4px;min-width:16px;padding:2px}.notice-popover{position:absolute;top:36px;right:0;width:320px;max-width:calc(100vw - 36px);max-height:430px;overflow:auto;background:#ffffff;border:1px solid var(--qs-line);border-radius:10px;box-shadow:0 15px 40px #0007;z-index:200;padding:18px}.notice-popover header{display:flex;justify-content:space-between;align-items:center}.notice-popover h2{font-size:14px;font-weight:500}.notice-popover button{font-size:10px}.notice-connection{font-size:9px;color:var(--qs-muted);margin:12px 0}.notice-popover ul{padding:0;list-style:none}.notice-popover li{padding:14px 0;border-top:1px solid var(--qs-line)}.notice-popover li p{font-size:12px;line-height:1.8}.notice-popover time{font-size:9px;color:var(--qs-muted);display:block;margin-top:7px}.notice-popover li.unread p{color:var(--qs-accent)}.notice-empty{font-size:11px;color:var(--qs-muted);padding:25px 0;text-align:center}@media(max-width:520px){.notice-popover{right:-75px}}
</style>
